 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    markers=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==5]
    if len(markers)<2:return g
    # Motif consists of colored cells connected to/near the first marker;
    # translate them by the marker-to-marker displacement.
    ar,ac=markers[0]; br,bc=markers[1]
    cells=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0,5) and abs(r-ar)<=3 and abs(c-ac)<=3:
                cells.append((r,c,grid[r][c]))
    for r,c,v in cells:
        rr,cc=r+(br-ar),c+(bc-ac)
        if 0<=rr<h and 0<=cc<w:g[rr][cc]=v
    return g
